def _update(self, event):
    """Update the slider position."""
    if self.ignore(event) or event.button != 1:
        return

    if event.name == 'button_press_event' and event.inaxes != self.ax:
        return

    if event.name == 'button_press_event' and not self.eventson:
        return

    # convert the event x/y to the slider axis
    if self.orientation == "horizontal":
        val = event.xdata
    else:
        val = event.ydata

    if not self.valmin <= val <= self.valmax:
        return

    if self.valstep is not None:
        val = self._stepped_value(val)

    if self.val == val:
        # We are done, no need to update anything.
        return

    self.set_val(val)

    if not self._observers:
        return
    if self.eventson:
        self._observers.process('changed', val)
```

